<?php declare(strict_types=1); namespace App\People\Application\Query\GetFamily; use App\People\Application\DTO\FamilyView; use App\People\Domain\Repository\FamilyRepository; use App\People\Domain\ValueObject\FamilyId; final readonly class GetFamilyHandler {public function __construct(private FamilyRepository $families){} public function __invoke(GetFamilyQuery $q):FamilyView{$f=$this->families->findById(FamilyId::fromString($q->id));if(!$f)throw new \RuntimeException('Family not found.');return new FamilyView($f->id()->toString(),$f->name(),array_map(fn($m)=>['personId'=>$m->personId()->toString(),'role'=>$m->role()->value,'createdAt'=>$m->createdAt()->format(DATE_ATOM)],$f->members()),$f->createdAt()->format(DATE_ATOM),$f->updatedAt()->format(DATE_ATOM));}}
